public class MonoBehaviour : Behaviour {
 // Test scheduler: coroutines run until their first yield, then advance with Scheduler.Tick()
 public Coroutine StartCoroutine(IEnumerator e){ var c=new Coroutine{owner=this}; c.stack.Push(e); Coroutine.all.Add(c); c.Step(); return c;} public Coroutine StartCoroutine(string s){return null;} public void StopCoroutine(Coroutine c){ if(c!=null) Coroutine.all.Remove(c);} public void StopCoroutine(string c){} public void StopAllCoroutines(){ Coroutine.all.RemoveAll(c=>ReferenceEquals(c.owner,this)); } public void Invoke(string m,float t){} public void InvokeRepeating(string m,float a,float b){} public void CancelInvoke(string m){} public void CancelInvoke(){} public bool IsInvoking(string m){return false;} public static void print(object o){} }
public class Coroutine { public static List<Coroutine> all=new List<Coroutine>(); public MonoBehaviour owner; public Stack<IEnumerator> stack=new Stack<IEnumerator>();
 public void Step(){ while(stack.Count>0){ var top=stack.Peek(); var cur=top.Current; if(cur is CustomYieldInstruction && ((CustomYieldInstruction)cur).keepWaiting) return; if(cur is WaitForSeconds && Time.time < ((WaitForSeconds)cur).end) return; if(!top.MoveNext()){ stack.Pop(); continue;} var n=top.Current; if(n is IEnumerator && !(n is CustomYieldInstruction)) { stack.Push((IEnumerator)n); continue;} return; } all.Remove(this); }
 public static void Tick(float dt){ Time.deltaTime=dt; Time.unscaledDeltaTime=dt; Time.time+=dt; Time.unscaledTime+=dt; Time.realtimeSinceStartup+=dt; foreach(var c in all.ToArray()){ if(!(bool)(Object)c.owner){ all.Remove(c); continue;} c.Step(); } }
 public static void Run(float seconds){ for(float t=0;t<seconds;t+=0.1f) Tick(0.1f); } }
public class YieldInstruction {}
public class WaitForSeconds : YieldInstruction { public float end; public WaitForSeconds(float s){end=Time.time+s;} }
public class WaitForSecondsRealtime : CustomYieldInstruction { float end; public WaitForSecondsRealtime(float s){end=Time.realtimeSinceStartup+s;} public override bool keepWaiting{get{return Time.realtimeSinceStartup<end;}} }
public abstract class CustomYieldInstruction : IEnumerator { public abstract bool keepWaiting{get;} public object Current{get{return null;}} public bool MoveNext(){return keepWaiting;} public void Reset(){} }
public class WaitForEndOfFrame : YieldInstruction {}
public class WaitUntil : CustomYieldInstruction { public WaitUntil(Func<bool> f){} public override bool keepWaiting{get{return false;}} }
public class WaitWhile : CustomYieldInstruction { public WaitWhile(Func<bool> f){} public override bool keepWaiting{get{return false;}} }
