public class GameObject : Object { public List<Component> comps=new List<Component>(); public GameObject():this("GameObject"){} public static List<GameObject> everything=new List<GameObject>(); public UnityEngine.SceneManagement.Scene scene; public GameObject(string n){name=n; var t=new RectTransform(); t.gameObject=this; comps.Add(t); everything.Add(this);} public GameObject(string n, params Type[] ts):this(n){ foreach(var t in ts) if(t!=typeof(RectTransform)&&t!=typeof(Transform)) AddComponent(t);} public Transform transform{get{return (Transform)comps[0];}} public bool activeSelf=true; public bool activeInHierarchy{get{return activeSelf;}} public string tag; public int layer; public void SetActive(bool b){activeSelf=b;}
 public Component AddComponent(Type t){var c=(Component)Activator.CreateInstance(t); c.gameObject=this; comps.Add(c); foreach(var m in new[]{"Awake","OnEnable"}){ var mi=t.GetMethod(m, System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic); if(mi!=null && mi.GetParameters().Length==0) mi.Invoke(c,null);} return c;} public T AddComponent<T>() where T:Component{return (T)AddComponent(typeof(T));} public T GetComponent<T>(){foreach(var c in comps) if(c is T) return (T)(object)c; return default(T);} public T GetComponentInChildren<T>(bool b){return GetComponentInChildren<T>();} public T GetComponentInChildren<T>(){ T c=GetComponent<T>(); if(c!=null) return c; foreach(var k in transform.kids){ c=k.gameObject.GetComponentInChildren<T>(); if(c!=null) return c;} return default(T);} public T[] GetComponents<T>(){var l=new List<T>(); foreach(var c in comps) if(c is T) l.Add((T)(object)c); return l.ToArray();} public T[] GetComponentsInChildren<T>(){return GetComponents<T>();} public T[] GetComponentsInChildren<T>(bool b){return GetComponents<T>();} public static GameObject Find(string s){return null;} public static GameObject FindGameObjectWithTag(string s){return null;} public static GameObject[] FindGameObjectsWithTag(string s){return null;} public static GameObject CreatePrimitive(PrimitiveType t){return new GameObject();} public void SendMessage(string m){} public void SendMessage(string m, object v, SendMessageOptions o){} public void SendMessage(string m, object v){} public bool CompareTag(string t){return true;} }
